import numpy as np
import sys

sys.path.append('storage/cognito')

try:
    from aps_with_lp_worker import run_grand_synthesis
except ImportError:
    print("Error: Could not import aps_with_lp_worker.py.")
    def run_grand_synthesis(): return None, None

def construct_packing() -> tuple:
    N_CIRCLES = 32
    centers, radii = run_grand_synthesis()

    if centers is not None and radii is not None:
      final_radii = radii * (1.0 - 1e-8)
      return centers, final_radii
    else:
      print("Algorithm failed, returning fallback.")
      return np.array([[0.1 + i*0.01, 0.1] for i in range(N_CIRCLES)]), np.full(N_CIRCLES, 0.001)
